"""Assemble measured reports without additional inference or provider calls."""
import json
from collections import Counter
from pathlib import Path
from datafactory.config.settings import get_settings
from datafactory.utils.atomic import atomic_json
from datafactory.research.export import snapshot


def read(path):
 return json.loads(path.read_text(encoding='utf-8'))


def main():
 s=get_settings(); root=s.reports_dir/'local_intelligence'
 smoke=read(root/'siglip_real_smoke.json'); current=read(root/'siglip_opportunities_final.json'); fresh=read(root/'siglip_opportunities.json'); priorities=read(root/'research_prioritization.json'); baseline=read(root/'research_baseline.json'); roundtrip=read(root/'research_roundtrip.json'); health=read(root/'local_ai_status.json')
 current['group_confidence']=dict(Counter(r['candidates'][0]['local']['confidence'] for r in current['rows']))
 current['fresh_pass_performance']={k:fresh[k] for k in ('model_load_seconds','total_seconds','inference_seconds','seconds_per_candidate','peak_working_set_mb','ranker_stats')}
 current['cache_reuse_performance']={k:current[k] for k in ('model_load_seconds','total_seconds','inference_seconds','seconds_per_candidate','peak_working_set_mb','ranker_stats')}
 current['thresholds']={k:v for k,v in read_config().items()}
 current['thresholds_scope']='Provisional, eight reference groups; source evidence is always required for acceptance.'
 smoke['counts'].update(clear_confidence_cases=sum(r['candidates'][0]['local'].get('confidence')=='HIGH' for r in smoke['rows']),ambiguous_cases=sum(r['candidates'][0]['local'].get('confidence')=='AMBIGUOUS' for r in smoke['rows']),low_confidence_cases=sum(r['candidates'][0]['local'].get('confidence')=='LOW' for r in smoke['rows']),incorrect_rankings=sum(r['correct_rank']!=1 for r in smoke['rows']))
 smoke['thresholds']=read_config()
 atomic_json(root/'siglip_real_smoke.json',smoke); atomic_json(root/'siglip_opportunities_final.json',current)
 positives=[c['local']['relevance'] for r in smoke['rows'] for c in r['candidates'] if c['correct_reference']]
 negatives=[c['local']['relevance'] for r in smoke['rows'] for c in r['candidates'] if not c['correct_reference']]
 lines=['# Provisional SigLIP calibration','','Eight visually checked, source-linked real photographs, each paired with two explicit cross-place distractors. Scores are sigmoid similarity values, not verified identity probabilities. Reference contact sheet: `scratch/siglip_reference_contact.png`. Model code follows the [model card](https://huggingface.co/google/siglip-base-patch16-224).','', '| POI | Correct rank | Wrong ranks | Correct score | Largest wrong score | Top margin | Decision |','|---|---:|---|---:|---:|---:|---|']
 for r in smoke['rows']:
  correct=next(c for c in r['candidates'] if c['correct_reference']); wrong=[c for c in r['candidates'] if not c['correct_reference']]
  lines.append(f"| {r['name']} | {r['correct_rank']} | {','.join(str(c['rank']) for c in wrong)} | {correct['local']['relevance']:.6f} | {max(c['local']['relevance'] for c in wrong):.6f} | {r['top_margin']:.6f} | {r['candidates'][0]['local']['confidence']} |")
 lines += ['', f"Top-1: 8/8. Top-3: 8/8 (weak measure with only three candidates). Clear cases: {smoke['counts']['clear_confidence_cases']}; ambiguous: {smoke['counts']['ambiguous_cases']}; low: {smoke['counts']['low_confidence_cases']}; incorrect: {smoke['counts']['incorrect_rankings']}.",'',f"Observed correct scores span {min(positives):.8f}–{max(positives):.6f}; largest distractor score {max(negatives):.6f}. The correct Bhrigu Lake image scores very low. LOW must not reject a photograph or invalidate strong source evidence.",'','The configurable high threshold is the midpoint between the moderate Galtaji reference (.618088) and the weakest high-score reference, City Palace (.869839). The minimum is the midpoint between the strongest distractor (.005826) and Kesar Kyari (.140758). The margin is the midpoint between Kesar Kyari (.134932) and Galtaji (.617865). This separates the observed clusters conservatively; it is not a universal validation threshold.','', '```json',json.dumps(read_config(),indent=2),'```','','HIGH requires a leading candidate, enough relevance and a margin over at least one competitor. Single-candidate groups remain ambiguous by score; deterministic P18 evidence can still resolve them. Model/revision changes disable this calibration. Same-place close candidates need source/identity assurance. The smoke is small and selected, not a held-out accuracy estimate. There are no qualifying cached cafe/food candidate groups, so that requested optional category was unavailable. No non-photo acceptance/rejection threshold was recalibrated without labelled non-photo data.','', f"Fresh smoke: {smoke['model_load_seconds']:.2f}s load; {smoke['inference_seconds']:.2f}s for 24 candidates in eight batches; {smoke['seconds_per_candidate']:.3f}s/candidate; {smoke['peak_working_set_mb']:.0f}MB peak working set. Cached weights were reused under HF_HUB_OFFLINE=1.",'']
 (root/'siglip_calibration.md').write_text('\n'.join(lines),encoding='utf-8')
 summary={'baseline_total':baseline['total'],'actionable_total':priorities['actionable_total'],'reduction_percent':round((baseline['total']-priorities['actionable_total'])/baseline['total']*100,2),'siglip':{k:v for k,v in smoke.items() if k!='rows'},'media_opportunities':{k:v for k,v in current.items() if k!='rows'},'health':health,'jaipur_batch_1':priorities['jaipur_batch_1'],'roundtrip':{k:v for k,v in roundtrip.items() if k not in ('dry_run','apply')},'preservation':{r['city']: {'source':r['source_unchanged'],'v3':r['original_v3_unchanged']} for r in priorities['cities']}}
 for old in baseline['cities']:
  assert snapshot(Path(old['pack']))==old['source_snapshot'] and snapshot(Path(old['pack']).parent/'v3')==old['v3_snapshot']
 atomic_json(root/'optimization_final.json',summary)
 lines=['# DataFactory optimization and validation','','## A. Baseline','','Before prioritization, all 1,637 tasks were preserved and audited in `research_baseline.json/md`. The old selector considered every REAL_PREFERRED POI important across unrelated fields and exported P4 by default. Raw missing fields therefore became human work even when not useful for itinerary planning.','', '| City | Raw unresolved | Optional old P4 | Required-media-policy tasks |','|---|---:|---:|---:|']
 for r in baseline['cities']: lines.append(f"| {r['city']} | {r['total']} | {r['optional_priority_P4']} | {r['by_media_policy'].get('REAL_REQUIRED',0)} |")
 type_counts=Counter();tier_counts=Counter();category_counts=Counter()
 for r in baseline['cities']:
  type_counts.update(r['by_type']);tier_counts.update(r['by_tier']);category_counts.update(r['by_category'])
 lines += ['', 'Baseline types: '+str(dict(type_counts))+'.', 'Baseline tiers: '+str(dict(tier_counts))+'.', 'Baseline categories: '+str(dict(category_counts))+'.','', 'The new deterministic rules classify 261 of these baseline conditions as DO_NOT_RESEARCH, 487 as OPTIONAL_DEFER, and 430 as useful P3 research for later. The complete per-task decisions remain in `research_prioritization.json`. Internal inventories additionally include ordinary gaps that the old selector never generated; their counts are deliberately separate from the fixed baseline.','', '## B. Real SigLIP','','Configured model: `'+smoke['model']+'`; revision `'+smoke['revision']+'`; actual weights downloaded into `data/cache/models`; real CPU inference PASS. Cache-only offline health also PASS. Duplicate, fuzzy text, geometry and hours checks PASS; optional semantic embeddings remain disabled.','', 'Eight POIs, 24 actual cached photographs; Top-1 8/8; Top-3 8/8; clear 5; ambiguous 2; correct-but-low 1; incorrect rankings 0. Detailed source pages, candidate paths, scores and ranks are in `siglip_real_smoke.json/md` and `siglip_calibration.md`.','', 'All 247 prior ranking opportunities were runnable locally (152 candidate groups). Failures: 0. Candidate confidence: HIGH 9; ambiguous 147; low relevance 91. Group confidence: HIGH 9; ambiguous 99; low 44. HIGH plus new strong source evidence: 0; new automatic image resolutions: 0.','', f"Fresh opportunity pass: {fresh['model_load_seconds']:.2f}s load; {fresh['inference_seconds']:.2f}s candidate processing; {fresh['total_seconds']:.2f}s total; {fresh['seconds_per_candidate']:.3f}s/candidate; {fresh['peak_working_set_mb']:.0f}MB peak working set. It ran 239 fresh predictions and reused eight scores. The later check reused all 247 score entries, taking {current['total_seconds']:.2f}s total (including release scanning and duplicate validation). Model weights were not downloaded again.",'', '## C. Cloud avoidance','','Actual live Groq calls: 0; Gemini: 0; paid: 0. Eight candidate groups are already resolved by existing verification/source evidence. 144 groups remain candidates for Groq assurance; these are routing requirements, not 144 measured provider requests. Gemini need is unknown until Groq availability/ambiguity is observed. 350 missing-image tasks have no usable cached candidate; they belong to research, not image inference. This is cached availability, not a fresh web search.','', 'Incremental measured cloud-call savings attributable to SigLIP: **0**. Nine decisive rankings alone do not prove POI identity; none qualified for additional safe automatic acceptance. Existing deterministic P18 acceptance already skipped cloud. Source contradictions are rejected before ranking; fallback and FREE_ONLY policies remain strict.','', '## D/E. Priority model and reduction','', '| City | Before | P0 | P1 | P2 | P3 | P4 | No research | Default | Reduction |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in priorities['cities']:
  c=r['baseline_by_priority']; lines.append(f"| {r['city']} | {r['baseline_raw_unresolved']} | "+' | '.join(str(c.get(k,0)) for k in ('P0','P1','P2','P3','P4','NO_RESEARCH'))+f" | {r['default_export']['total']} | {r['reduction_percent']}% |")
 lines += ['',f"Total: 1,637 → {priorities['actionable_total']} actionable tasks, a {summary['reduction_percent']}% reduction. Default is P0/P1/P2; --all includes P3/P4; DO_NOT_RESEARCH stays internal. Stable IDs and priority/tier/relevance/prominence/category/place/type order survive batching.",'','## F. Jaipur Batch 1','', '75 tasks: 50 REAL_PRIMARY_IMAGE, 4 COORDINATE_RESEARCH, 15 OPENING_HOURS, 1 DESCRIPTION, 5 WEBSITE, 0 IDENTITY_RESEARCH. P0 53, P1 1, P2 21. All 50 required-photo tasks are included; 35 other actionable tasks remain beyond this cap.','', 'Exact files:', '', '- `'+str(s.data_dir/'research/exports/jaipur/batch_1/research_handoff.json')+'`','- `'+str(s.data_dir/'research/exports/jaipur/batch_1/research_handoff.md')+'`','- Focused required-image handoff (50 tasks): `'+str(s.data_dir/'research/exports/jaipur/required_images/research_handoff.md')+'`','- Focused core-hours handoff (24 tasks): `'+str(s.data_dir/'research/exports/jaipur/core_hours/research_handoff.md')+'`','', 'Each directory includes JSON, Markdown, CSV, exact results template, strict JSON Schema and a separate internal inventory.','', '## G. Safe round trip','','`python -m scripts.verify_research_roundtrip` generated an isolated synthetic release and handoff, validated registered task/place IDs through CLI `research-import --dry-run` (exit 0), then CLI `research-import --apply` (exit 0). The explicit fixture router replaces cloud. Hours syntax, source retention, legal metadata/file/duplicate/local-media checks and established assurance all ran. Apply performed the full JSON/JSONL/Parquet/SQLite/media/checksum offline rebuild; release validation passed. Only opening_hours and images changed; two provenance rows were stored; the original fixture v3 was preserved.','', 'Fixture readiness changed from general 0%/required coverage 0%/not ready to 100%/100%/ready. This is fixture evidence only; no synthetic fact, license or source result was applied to production. See `research_roundtrip.json/md` for exact fixture paths and decisions.','', '## H. Commands and tests','','```powershell','python -m datafactory.cli local-ai-status --download',"$env:HF_HUB_OFFLINE = '1'",'python -m datafactory.cli local-ai-status','python -m datafactory.cli local-ai-smoke --fixture tests/fixtures/siglip_real_cases.json --refresh-scores --output reports/local_intelligence/siglip_real_smoke','python -m datafactory.cli local-ai-smoke --output reports/local_intelligence/siglip_opportunities','python -m datafactory.cli local-ai-smoke --output reports/local_intelligence/siglip_opportunities_final','python -m scripts.report_research_optimization','python -m scripts.verify_research_roundtrip','python -m pytest -q --basetemp scratch/pytest-optimization-final-review -o cache_dir=scratch/pytest-cache --tb=short','python -m pip check','```','', 'Actual final pytest output:','```', (root/'tests_final.txt').read_text(encoding='utf-8').strip(),'```','', 'pip check: no broken requirements. Normal tests disable real model loads; opt-in smoke uses actual cached weights. Earlier test setup failed on the host shared temp-directory ACL; workspace --basetemp resolves it. Dependency versions: torch 2.14.1+cpu, transformers 4.57.6, sentencepiece 0.2.2, protobuf 6.33.6.','', '## I. Readiness and limits','', '| City | General usability | Required media coverage | Source ready | Original v3 preserved |','|---|---:|---:|---|---|']
 for r in priorities['cities']: lines.append(f"| {r['city']} | {r['readiness']['GENERAL_USABILITY']}% | {r['readiness']['REAL_REQUIRED_MEDIA_COVERAGE']}% | {r['readiness']['SOURCE_DATA_READY']} | {r['original_v3_unchanged']} |")
 lines += ['', 'Required coverage now counts renderable, legally attributed, verified real media. Source readiness still requires >=95% general usability, 100% required coverage and all critical gates. Existing app fallbacks are not bundled source photographs and cannot inflate either metric. Production packs remain source-unready; this pass provides prioritization and validated local tooling, not new external source data.','', 'Calibration is provisional and derived from eight selected cases, not a universal or held-out accuracy threshold. Top-3 is weak with three candidates. No qualifying cached food/cafe group was available. Real inference is proven, but wider identity calibration remains future work. Gemini demand cannot be measured without cloud responses, and no free quota was spent just to populate a report. Model downloads needed network escalation; later inference and health ran offline. Production release and original v3 snapshots remain unchanged across all four cities. No City Lab files, paid API, vector DB, local LLM or new provider were introduced.','', 'Review skill: user requirements served as the benchmark. Scope/pipeline boundaries and strict import safety passed review. Remaining dataset-readiness and statistical-calibration limits are reported above; no critical implementation defect was found in the checked paths.','']
 (root/'optimization_final.md').write_text('\n'.join(lines),encoding='utf-8')
 print(json.dumps({'actionable':priorities['actionable_total'],'reduction_percent':summary['reduction_percent'],'final_report':str(root/'optimization_final.md'),'tests':(root/'tests_final.txt').read_text(encoding='utf-8').splitlines()[-1]},indent=2))


def read_config():
 from datafactory.local_intelligence.config import LocalConfig
 c=LocalConfig(); return {'high_relevance':c.local_media_relevance_threshold,'min_relevance':c.local_media_min_relevance,'ambiguity_margin':c.local_media_ambiguity_margin}


if __name__=='__main__': main()
